 "content": "def transform(grid):
    out=[row[:] for row in grid]
    bg=grid[0][0]
    for r,row in enumerate(grid):
        marks=[c for c,v in enumerate(row) if v!=bg]
        if len(marks)>=2:
            # fill intervening cells with the next color after the marked color
            color=row[marks[0]]
            fill=(color+1)%10
            for a,b in zip(marks,marks[1:]):
                for c in range(a+1,b):
                    out[r][c]=fill
    return out
